USE RestaurantSalesDB;
GO

-- =====================================================
-- 15. AVERAGE COMPLETED SALES PER CUSTOMER
-- =====================================================

-- Calculate the average completed sales revenue
-- generated by customers who have completed orders.

SELECT
    AVG(CustomerSales) AS AverageCustomerSales
FROM (
    SELECT
        o.CustomerID,
        SUM(oi.Quantity * oi.UnitPrice) AS CustomerSales
    FROM Orders AS o
    INNER JOIN OrderItems AS oi
        ON o.OrderID = oi.OrderID
    WHERE o.OrderStatus = 'Completed'
    GROUP BY o.CustomerID
) AS CustomerTotals;

-- =====================================================
-- 16. ABOVE-AVERAGE CUSTOMER SALES
-- =====================================================

-- Identify customers whose completed sales exceed
-- the average completed sales per customer.

SELECT
    c.CustomerID,
    c.CustomerName,
    SUM(oi.Quantity * oi.UnitPrice) AS TotalSales
FROM Customers AS c
INNER JOIN Orders AS o
    ON c.CustomerID = o.CustomerID
INNER JOIN OrderItems AS oi
    ON o.OrderID = oi.OrderID
WHERE o.OrderStatus = 'Completed'
GROUP BY
    c.CustomerID,
    c.CustomerName
HAVING SUM(oi.Quantity * oi.UnitPrice) > (
    SELECT AVG(CustomerSales)
    FROM (
        SELECT
            o.CustomerID,
            SUM(oi.Quantity * oi.UnitPrice) AS CustomerSales
        FROM Orders AS o
        INNER JOIN OrderItems AS oi
            ON o.OrderID = oi.OrderID
        WHERE o.OrderStatus = 'Completed'
        GROUP BY o.CustomerID
    ) AS CustomerTotals
)
ORDER BY TotalSales DESC;

-- =====================================================
-- 17. ABOVE-AVERAGE CUSTOMER SALES USING CTE
-- =====================================================

-- Calculate customer sales using a CTE and identify
-- customers whose sales exceed the customer average.

WITH CustomerSales AS (
    SELECT
        c.CustomerID,
        c.CustomerName,
        SUM(oi.Quantity * oi.UnitPrice) AS TotalSales
    FROM Customers AS c
    INNER JOIN Orders AS o
        ON c.CustomerID = o.CustomerID
    INNER JOIN OrderItems AS oi
        ON o.OrderID = oi.OrderID
    WHERE o.OrderStatus = 'Completed'
    GROUP BY
        c.CustomerID,
        c.CustomerName
)
SELECT
    CustomerID,
    CustomerName,
    TotalSales
FROM CustomerSales
WHERE TotalSales > (
    SELECT AVG(TotalSales)
    FROM CustomerSales
)
ORDER BY TotalSales DESC;
